                new_v = ops.cond(
                    is_update_step, lambda: new_g, lambda: v.value
                )
                v.assign(new_v)
                acc_g.assign(new_g_acc)
            else:
                v.assign(g)
            filtered_grads.pop(i)
            filtered_vars.pop(i)
    return filtered_grads, filtered_vars

